//! `data/generated.json` is exactly what the generator makes of the vendored document and the
//! live catalog, and the generator refuses every input it cannot read exactly.

use oce_vocab::{GENERATED_JSON, Side};
use serde_json::{Value, json};

use crate::generator::core::{Core, ID_BASE, MAX_CORE_BYTES};
use crate::generator::walk::{ClassWalk, ConnectorWalk, catalog_walk};
use crate::generator::{GenerateError, generate, regenerate};
use crate::support::{BLESS_SWITCH, core_bytes, crate_dir};

/// Compare regenerated bytes with the checked-in file, naming the first line that differs.
fn stale(checked_in: &str, regenerated: &str) -> Result<(), String> {
    if checked_in == regenerated {
        return Ok(());
    }
    let line = checked_in
        .lines()
        .zip(regenerated.lines())
        .take_while(|(old, new)| old == new)
        .count();
    Err(format!(
        "data/generated.json is stale from line {}:\n  checked in:  {}\n  regenerated: {}\nrerun with {BLESS_SWITCH}=1 if the change is intended",
        line + 1,
        checked_in.lines().nth(line).unwrap_or("<end of file>"),
        regenerated.lines().nth(line).unwrap_or("<end of file>"),
    ))
}

#[test]
fn generated_json_is_what_the_generator_makes_of_the_vendored_document() {
    let regenerated = regenerate(core_bytes()).expect("the vendored document generates");
    let path = crate_dir().join("data/generated.json");
    if oce_bless::enabled(BLESS_SWITCH) {
        std::fs::write(&path, &regenerated).expect("write data/generated.json");
        return;
    }
    let on_disk = std::fs::read_to_string(&path).expect("read data/generated.json");
    stale(&on_disk, &regenerated).unwrap_or_else(|error| panic!("{error}"));
    assert_eq!(GENERATED_JSON, on_disk, "the compiled-in copy is the file");
}

#[test]
fn regeneration_is_byte_stable_across_two_runs() {
    let first = regenerate(core_bytes()).expect("first run");
    let second = regenerate(core_bytes()).expect("second run");
    assert_eq!(first, second);
    assert!(first.ends_with("}\n") && !first.contains('\r'));
}

fn core() -> Core {
    Core::parse(core_bytes()).expect("the vendored document parses")
}

fn walk() -> Vec<ClassWalk> {
    catalog_walk().expect("the catalog walks")
}

fn rendered(walk: &[ClassWalk]) -> Result<String, GenerateError> {
    generate(&core(), walk).map(|generated| generated.to_json())
}

fn class_mut<'a>(walk: &'a mut [ClassWalk], class_path: &str) -> &'a mut ClassWalk {
    walk.iter_mut()
        .find(|class| class.class_path == class_path)
        .unwrap_or_else(|| panic!("{class_path} is walked"))
}

fn missing(class: &str, subject: &str) -> GenerateError {
    GenerateError::MissingNode {
        class: class.to_owned(),
        subject: subject.to_owned(),
    }
}

#[test]
fn a_renamed_port_fails_the_generator_by_name_and_the_comparison() {
    let mut walk = walk();
    class_mut(&mut walk, "CDL.Reals.PID").connectors[0].name = "u_set".to_owned();
    assert_eq!(rendered(&walk), Err(missing("CDL.Reals.PID", "u_set")));

    // A rename onto a name upstream also has still moves the bytes: the entry's name, and the
    // description that is now another connector's.
    let mut walk = self::walk();
    let pid = class_mut(&mut walk, "CDL.Reals.PID");
    assert_eq!(pid.connectors[0].name, "u_s");
    pid.connectors[0].name = "u_m".to_owned();
    let moved = rendered(&walk).expect("both names exist upstream");
    let error = stale(GENERATED_JSON, &moved).expect_err("a renamed port is stale");
    assert!(
        error.contains("\"description\": \"Measurement input signal\""),
        "{error}"
    );
}

#[test]
fn a_renamed_parameter_fails_the_generator_by_name() {
    let mut walk = walk();
    class_mut(&mut walk, "CDL.Logical.TrueDelay").parameters[0] = "delay".to_owned();
    assert_eq!(
        rendered(&walk),
        Err(missing("CDL.Logical.TrueDelay", "delay"))
    );
}

#[test]
fn a_removed_class_fails_the_comparison() {
    let mut walk = walk();
    let removed = walk.remove(7);
    let shorter = rendered(&walk).expect("the remaining classes generate");
    assert!(!shorter.contains(&format!("\"class\": \"{}\"", removed.class_path)));
    let error = stale(GENERATED_JSON, &shorter).expect_err("a removed class is stale");
    assert!(error.contains(&removed.class_path), "{error}");
}

#[test]
fn a_class_the_document_lacks_fails_the_generator_unless_it_is_pinned_absent() {
    let mut walk = walk();
    walk[0].class_path = "CDL.Reals.Sources.Constantly".to_owned();
    assert_eq!(
        rendered(&walk),
        Err(missing("CDL.Reals.Sources.Constantly", ""))
    );
}

#[test]
fn an_added_class_or_connector_fails_the_generator_by_name() {
    let mut extra_connector = walk();
    class_mut(&mut extra_connector, "CDL.Reals.Add")
        .connectors
        .push(ConnectorWalk {
            name: "u3".to_owned(),
            side: Side::Input,
            dims: 0,
        });
    assert_eq!(
        rendered(&extra_connector),
        Err(missing("CDL.Reals.Add", "u3"))
    );

    let mut extra_class = walk();
    extra_class.push(ClassWalk {
        class_path: "CDL.Reals.Brand".to_owned(),
        connectors: Vec::new(),
        parameters: Vec::new(),
    });
    assert_eq!(rendered(&extra_class), Err(missing("CDL.Reals.Brand", "")));
}

#[test]
fn an_edited_generated_json_fails_the_comparison() {
    let fresh = regenerate(core_bytes()).expect("generates");
    for (from, to) in [
        ("Setpoint input signal", "Setpoint input"),
        ("\"unit\": \"s\"", "\"unit\": \"min\""),
        ("\"upstream\": false", "\"upstream\": true"),
        ("\"dims\": 1", "\"dims\": 0"),
    ] {
        assert!(GENERATED_JSON.contains(from), "{from}");
        let edited = GENERATED_JSON.replacen(from, to, 1);
        let error = stale(&edited, &fresh).expect_err(from);
        assert!(error.contains("stale from line"), "{error}");
    }
    // An appended byte and a dropped final newline are stale too.
    assert!(stale(&format!("{GENERATED_JSON}\n"), &fresh).is_err());
    assert!(stale(GENERATED_JSON.trim_end(), &fresh).is_err());
    assert_eq!(stale(GENERATED_JSON, &fresh), Ok(()));
}

/// The vendored document with `edit` applied to its graph.
fn perturbed(edit: impl FnOnce(&mut Vec<Value>)) -> Vec<u8> {
    let mut document: Value = serde_json::from_slice(core_bytes()).expect("JSON");
    edit(document["@graph"].as_array_mut().expect("@graph"));
    serde_json::to_vec(&document).expect("serialize")
}

fn node_mut<'a>(graph: &'a mut [Value], member: &str) -> &'a mut Value {
    let id = format!("{ID_BASE}{member}");
    graph
        .iter_mut()
        .find(|node| node["@id"] == id.as_str())
        .unwrap_or_else(|| panic!("{id} is in the document"))
}

#[test]
fn a_changed_upstream_description_fails_the_comparison() {
    let bytes = perturbed(|graph| {
        node_mut(graph, "CDL.Reals.PID.Ti")["S231:description"] = json!("Integrator time");
    });
    let moved = regenerate(&bytes).expect("still generates");
    let error = stale(GENERATED_JSON, &moved).expect_err("a changed description is stale");
    assert!(error.contains("Integrator time"), "{error}");
}

#[test]
fn a_dropped_upstream_node_fails_the_generator_naming_the_subject() {
    let dropped_connector = perturbed(|graph| {
        let id = format!("{ID_BASE}CDL.Reals.PID.u_m");
        graph.retain(|node| node["@id"] != id.as_str());
    });
    assert_eq!(
        regenerate(&dropped_connector),
        Err(missing("CDL.Reals.PID", "u_m"))
    );
    let dropped_class = perturbed(|graph| {
        let id = format!("{ID_BASE}CDL.Reals.PID");
        graph.retain(|node| node["@id"] != id.as_str());
    });
    assert_eq!(
        regenerate(&dropped_class),
        Err(missing("CDL.Reals.PID", ""))
    );
}

#[test]
fn a_node_for_a_member_pinned_as_absent_fails_the_generator() {
    let gained_member = perturbed(|graph| {
        graph.push(json!({
            "@id": format!("{ID_BASE}CDL.Reals.MatrixGain.nin"),
            "@type": "S231:Parameter",
            "S231:description": "Number of inputs",
        }));
    });
    assert_eq!(
        regenerate(&gained_member),
        Err(GenerateError::UnexpectedNode {
            class: "CDL.Reals.MatrixGain".to_owned(),
            subject: "nin".to_owned(),
        })
    );
    let gained_class = perturbed(|graph| {
        graph.push(json!({
            "@id": format!("{ID_BASE}CDL.Logical.TrueHoldWithReset"),
            "@type": "S231:ElementaryBlock",
        }));
    });
    assert_eq!(
        regenerate(&gained_class),
        Err(GenerateError::UnexpectedNode {
            class: "CDL.Logical.TrueHoldWithReset".to_owned(),
            subject: String::new(),
        })
    );
}

fn malformed(member: (&str, &str), field: &'static str) -> GenerateError {
    GenerateError::MalformedNode {
        class: member.0.to_owned(),
        subject: member.1.to_owned(),
        field,
    }
}

#[test]
fn a_malformed_upstream_node_fails_the_generator_naming_the_field() {
    let ti = ("CDL.Reals.PID", "Ti");
    for (field, value) in [
        ("S231:description", json!("")),
        ("S231:description", json!(["Time constant"])),
        ("S231:description", Value::Null),
        ("qudt:hasUnit", json!("unit:SEC")),
        ("qudt:hasUnit", json!({"@id": "unit:SEC", "extra": 1})),
        ("qudt:hasUnit", json!({"@id": 7})),
        ("qudt:hasQuantityKind", json!([{"@id": "q:Time"}])),
        ("@type", json!("S231:RealInput")),
        ("@type", json!(["S231:Parameter"])),
    ] {
        let bytes = perturbed(|graph| node_mut(graph, "CDL.Reals.PID.Ti")[field] = value.clone());
        assert_eq!(
            regenerate(&bytes),
            Err(malformed(ti, field)),
            "{field} = {value}"
        );
    }
    let no_description = perturbed(|graph| {
        let node = node_mut(graph, "CDL.Reals.PID.Ti")
            .as_object_mut()
            .expect("object");
        node.remove("S231:description");
    });
    assert_eq!(
        regenerate(&no_description),
        Err(malformed(ti, "S231:description"))
    );
    // A connector looked up where upstream has a parameter of that name, and the reverse.
    let wrong_side = perturbed(|graph| {
        node_mut(graph, "CDL.Reals.PID.u_s")["@type"] = json!("S231:RealOutput");
    });
    assert_eq!(
        regenerate(&wrong_side),
        Err(malformed(("CDL.Reals.PID", "u_s"), "@type"))
    );
}

#[test]
fn an_unknown_unit_or_quantity_identifier_fails_the_generator_naming_the_subject() {
    for identifier in [
        "unit:FURLONG",
        "unit:",
        "unit:sec",
        "q:Time",
        "SEC",
        "",
        "S231:",
    ] {
        let bytes = perturbed(|graph| {
            node_mut(graph, "CDL.Reals.PID.Ti")["qudt:hasUnit"] = json!({ "@id": identifier });
        });
        assert_eq!(
            regenerate(&bytes),
            Err(GenerateError::UnknownUnit {
                class: "CDL.Reals.PID".to_owned(),
                subject: "Ti".to_owned(),
                identifier: identifier.to_owned(),
            }),
            "{identifier}"
        );
    }
    for identifier in ["q:Luminosity", "q:time", "unit:SEC", "Time", ""] {
        let bytes = perturbed(|graph| {
            node_mut(graph, "CDL.Reals.PID.Ti")["qudt:hasQuantityKind"] =
                json!({ "@id": identifier });
        });
        assert_eq!(
            regenerate(&bytes),
            Err(GenerateError::UnknownQuantity {
                class: "CDL.Reals.PID".to_owned(),
                subject: "Ti".to_owned(),
                identifier: identifier.to_owned(),
            }),
            "{identifier}"
        );
    }
}

#[test]
fn a_quantity_kind_with_two_inverses_refuses_on_a_subject_without_a_pinned_resolution() {
    let bytes = perturbed(|graph| {
        node_mut(graph, "CDL.Reals.PID.Ti")["qudt:hasQuantityKind"] = json!({"@id": "q:Pressure"});
    });
    assert_eq!(
        regenerate(&bytes),
        Err(GenerateError::AmbiguousQuantity {
            class: "CDL.Reals.PID".to_owned(),
            subject: "Ti".to_owned(),
            identifier: "q:Pressure".to_owned(),
        })
    );
    // The one pinned subject resolves, and only to a quantity the kind can stand for.
    let fresh = regenerate(core_bytes()).expect("generates");
    assert_eq!(fresh.matches("\"quantity\": \"Pressure\"").count(), 1);
}

#[test]
fn an_s231_fallback_unit_carries_the_original_string_in_either_spelling() {
    for identifier in ["S231:1/s", "http://data.ashrae.org/S231#1/s"] {
        let bytes = perturbed(|graph| {
            node_mut(graph, "CDL.Reals.PID.Ti")["qudt:hasUnit"] = json!({ "@id": identifier });
        });
        let moved = regenerate(&bytes).expect("a fallback unit generates");
        let error = stale(GENERATED_JSON, &moved).expect_err("the unit moved");
        assert!(error.contains("\"unit\": \"1/s\""), "{error}");
    }
}

#[test]
fn a_document_that_is_not_the_expected_shape_is_refused_with_a_typed_error() {
    let parse = |bytes: &[u8]| Core::parse(bytes).map(|_| ());
    assert!(matches!(parse(b"{"), Err(GenerateError::CoreNotJson(_))));
    assert!(matches!(parse(b""), Err(GenerateError::CoreNotJson(_))));
    assert!(matches!(
        parse(b"\xff\xfe"),
        Err(GenerateError::CoreNotJson(_))
    ));
    for document in [
        json!([]),
        json!({}),
        json!({"@graph": {}}),
        json!({"@graph": [1]}),
        json!({"@graph": [{"S231:label": "no id"}]}),
        json!({"@graph": [{"@id": 3}]}),
    ] {
        let bytes = serde_json::to_vec(&document).expect("serialize");
        assert!(
            matches!(parse(&bytes), Err(GenerateError::CoreShape(_))),
            "{document}"
        );
    }
    let twice = json!({"@graph": [{"@id": "S231:a"}, {"@id": "S231:a"}]});
    assert_eq!(
        parse(&serde_json::to_vec(&twice).expect("serialize")),
        Err(GenerateError::DuplicateNode {
            id: "S231:a".to_owned()
        })
    );
    // An empty graph parses and then fails on the first catalog class.
    let empty = serde_json::to_vec(&json!({"@graph": []})).expect("serialize");
    assert_eq!(
        regenerate(&empty),
        Err(missing("CDL.Reals.Sources.Constant", ""))
    );
}

#[test]
fn the_document_size_bound_accepts_the_limit_and_refuses_one_byte_more() {
    let mut padded = b"{\"@graph\":[]}".to_vec();
    padded.resize(MAX_CORE_BYTES, b' ');
    assert!(Core::parse(&padded).is_ok());
    padded.push(b' ');
    assert_eq!(
        Core::parse(&padded).map(|_| ()),
        Err(GenerateError::CoreTooLarge {
            bytes: MAX_CORE_BYTES + 1,
            limit: MAX_CORE_BYTES,
        })
    );
}
